package org.diy.liferecorder;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.io.*;
/** One owner for both scheduled and foreground speech work. */
final class OfflineProcessor {
 private static final java.util.concurrent.atomic.AtomicBoolean occupied=new java.util.concurrent.atomic.AtomicBoolean();
 static volatile String activeId="",status="暂无离线任务";
 static boolean stillRunning(RecordStore db,String id)throws Exception{JSONArray state=db.rows("SELECT status FROM jobs WHERE id=?",id);return state.length()>0&&state.getJSONObject(0).optString("status").equals("running");}
 static boolean busy(){return occupied.get();}
 static String hold(Context c,boolean automatic){ActivityManager.MemoryInfo m=new ActivityManager.MemoryInfo();((ActivityManager)c.getSystemService(Context.ACTIVITY_SERVICE)).getMemoryInfo(m);if(m.lowMemory||m.availMem<256L*1024*1024)return "等待释放内存";PowerManager p=(PowerManager)c.getSystemService(Context.POWER_SERVICE);if(Build.VERSION.SDK_INT>=29&&p.getCurrentThermalStatus()>=PowerManager.THERMAL_STATUS_CRITICAL)return "温度达到临界级别，已暂停；降温后自动继续";if(automatic&&p.isPowerSaveMode())return "等待退出省电模式";return "";}
 static String waiting(Context c,JSONObject job)throws Exception{if(c.getSharedPreferences("offline-scheduling",0).getBoolean("paused",false))return "已暂停 · 点击立即处理继续";boolean automatic=job.has("input")?new JSONObject(job.getString("input")).optBoolean("automatic"):job.optInt("automatic")==1;OfflinePacks packs=new OfflinePacks(c);String pack=job.has("input")?new JSONObject(job.getString("input")).optString("pack",packs.selected()):packs.selected();String language=job.has("input")?new JSONObject(job.getString("input")).optString("language",AppLanguage.code(c)):AppLanguage.code(c);if(job.has("input")&&new JSONObject(job.getString("input")).optBoolean("speaker_only"))pack="speaker";else if(language.equals("en"))pack="standard";if(!pack.isEmpty()&&!packs.ready(pack))return "等待下载并验证语音包";if(automatic&&packs.chargingOnly()&&!((BatteryManager)c.getSystemService(Context.BATTERY_SERVICE)).isCharging())return "等待充电 · 可点击立即处理";String hold=hold(c,automatic);return hold.isEmpty()?"等待系统调度 · 可点击立即处理":hold;}
 /** Returns true when a later system retry is useful. Foreground mode processes explicitly selected jobs. */
 static boolean drain(Context context,boolean manualOnly,ProviderClient.Cancel stop){if(context.getSharedPreferences("offline-scheduling",0).getBoolean("paused",false))return false;if(!occupied.compareAndSet(false,true))return true;boolean retry=false;try(RecordStore db=new RecordStore(context)){
  while(!stop.cancelled()){
   JSONArray rows=db.rows("SELECT * FROM jobs WHERE type='local_asr' AND status='queued' "+(manualOnly?"AND input LIKE '%\"automatic\":false%' ":"")+"ORDER BY CASE WHEN input LIKE '%\"automatic\":false%' THEN 0 ELSE 1 END,created LIMIT 1");if(rows.length()==0)break;JSONObject job=rows.getJSONObject(0),input=new JSONObject(job.getString("input"));String id=job.getString("id"),source=job.getString("source");boolean automatic=input.optBoolean("automatic");OfflinePacks packs=new OfflinePacks(context);
   if(automatic&&!packs.automatic()){db.update("jobs",id,"status","cancelled");TaskProgress.set(db,id,"自动处理已关闭",0,0,"");continue;}
   if(automatic&&packs.chargingOnly()&&!((BatteryManager)context.getSystemService(Context.BATTERY_SERVICE)).isCharging()){status="等待充电";TaskProgress.set(db,id,"等待充电",0,0,"");break;}
   String selectedPack=input.optBoolean("speaker_only")?"speaker":input.optString("language",AppLanguage.code(context)).equals("en")?"standard":input.optString("pack");if(!packs.ready(selectedPack)){status="等待下载并验证语音包";TaskProgress.set(db,id,status,0,0,"");retry=true;break;}String hold=hold(context,automatic);if(!hold.isEmpty()){status=hold;TaskProgress.set(db,id,hold,0,0,"");retry=true;break;}
   activeId=id;OfflineJobService.status=status="正在本机整理";db.update("jobs",id,"status","running");TaskProgress.set(db,id,"校验录音",0,0,"");
   final long[] checked={0,0};final boolean[] cancelled={false};final String[] resource={""};ProviderClient.Cancel cancel=()->{if(stop.cancelled())return true;long now=SystemClock.elapsedRealtime();if(now-checked[1]>=2000){resource[0]=hold(context,automatic);checked[1]=now;}if(!resource[0].isEmpty())return true;if(now-checked[0]>=250){try{cancelled[0]=context.getSharedPreferences("offline-scheduling",0).getBoolean("paused",false)||!stillRunning(db,id);}catch(Exception e){cancelled[0]=true;}checked[0]=now;}return cancelled[0];};
   try{long before=SystemClock.elapsedRealtime();JSONObject current=db.audio(source);if(!current.optString("path").equals(input.getString("asset_path")))throw new IOException("音频资产已改变，请重新转写");if(!org.diy.lifecore.LocalSecurity.hash(new File(input.getString("asset_path"))).equals(input.getString("asset_sha")))throw new IOException("音频校验失败");
    TaskProgress.set(db,id,"等待离线引擎",0,0,"");OfflineSpeech.Progress progress=(phase,done,total,unit)->{status=phase;OfflineJobService.status=phase;TaskProgress.set(db,id,phase,done,total,unit);};JSONObject result=input.optBoolean("speaker_only")?OfflineSpeech.rematch(packs,input.optString("pack"),new File(input.getString("asset_path")),new JSONObject(current.getString("speech_json")),cancel,progress):OfflineSpeech.transcribe(packs,selectedPack,new File(input.getString("asset_path")),cancel,progress,input.optString("language",AppLanguage.code(context)));if(!input.optBoolean("speaker_only"))OfflineSpeech.mapToOriginal(result,current);long duration=SystemClock.elapsedRealtime()-before;result.put("pipeline_ms",duration).put("execution",context instanceof OfflineRunService?"foreground":"scheduled");if(cancel.cancelled())throw new IOException("处理已中断");db.update("jobs",id,"result",result.toString());
    db.getWritableDatabase().beginTransaction();try{if(cancel.cancelled()||!stillRunning(db,id))throw new IOException("处理已中断");current=db.audio(source);if(current.optLong("transcript_revision")!=input.getLong("transcript_revision")||!current.optString("transcript").equals(input.getString("transcript_before"))||!current.optString("path").equals(input.getString("asset_path")))throw new IOException("原文或音频已修改，结果留在任务中，请核对");LifeMemory.invalidate(db,source);db.getWritableDatabase().execSQL("UPDATE facts SET state='review' WHERE source=? AND state<>'inactive'",new Object[]{source});db.getWritableDatabase().execSQL("UPDATE tasks SET state='review' WHERE source=? AND state<>'done'",new Object[]{source});android.content.ContentValues values=new android.content.ContentValues();values.put("transcript",result.getString("text"));values.put("speech_json",result.toString());values.put("transcript_revision",current.optLong("transcript_revision")+1);values.put("analysis","");db.getWritableDatabase().update("audio",values,"id=?",new String[]{source});db.update("jobs",id,"status","done");db.update("jobs",id,"error","");HourlyAutomation.schedule(db.context,true);TaskProgress.set(db,id,input.optBoolean("speaker_only")?"声纹已更新，原文保留":result.optString("text").isEmpty()?"处理完成 · 未识别到文字":"已完成并保存转写",1,1,"任务");db.getWritableDatabase().setTransactionSuccessful();}finally{db.getWritableDatabase().endTransaction();}
    if(!input.optBoolean("speaker_only")){String pack=input.getString("pack");double rtf=duration/(double)Math.max(1,current.optLong("duration"));int slow=packs.prefs.getInt(pack+"-slow-count",0);packs.prefs.edit().putString(pack+"-runtime",new JSONObject().put("pipeline_ms",duration).put("audio_ms",current.optLong("duration")).put("rtf",rtf).toString()).putInt(pack+"-slow-count",rtf>.6?Math.min(5,slow+1):Math.max(0,slow-1)).apply();}status=input.optBoolean("speaker_only")?"声纹匹配已完成":"离线转写已完成";
   }catch(Throwable error){JSONArray states=db.rows("SELECT status FROM jobs WHERE id=?",id);if(states.length()>0&&!states.getJSONObject(0).optString("status").equals("cancelled")){boolean defer=stop.cancelled()||context.getSharedPreferences("offline-scheduling",0).getBoolean("paused",false)||!hold(context,automatic).isEmpty();String reason=defer?"系统调度暂停，稍后继续":error.getMessage()==null?"离线处理失败，请验证资源包":error.getMessage();db.update("jobs",id,"status",defer?"queued":"failed");db.update("jobs",id,"error",reason);TaskProgress.set(db,id,reason,0,0,"");status=reason;if(defer){retry=true;break;}}}finally{activeId="";}
  }
 }catch(Exception e){status="离线任务待恢复";retry=true;}finally{activeId="";occupied.set(false);}return retry;}
}
